<script setup lang="ts">
import { onBeforeUnmount,onMounted,ref,watch } from 'vue'
import * as THREE from 'three'
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js'
import { ARC_POOL_SIZE,visibleSlots,type ArcSnapshot,type Entry } from './arc-engine'
import { inspectModel,slotTransform } from './arc-model'
import {sceneViewport,pointerNdc,exitScenePose,sampleExitScene,sceneRootMatrix,type ExitSceneSnapshot,sceneLighting,themeSceneMaterial,type SceneTheme} from './scene-presentation'
import {entryScenePose} from './entry-choreography'
import {readingMaterial} from './read-material'
import {bindOpticalActivity,makeOpticalActivity,updateOpticalActivity,type OpticalActivity,type ReadActivityMode} from './read-activity'
import {bindReadingIdentity,isReadingSelected,readingFocusWeight,makeReadingMotion,updateReadingMotion,type ReadingMotion} from './read-motion'
const props=defineProps<{frame:ArcSnapshot;entries:readonly Entry[];reduced:boolean;disabled?:boolean;entryProgress?:number;activity?:ReadActivityMode;theme?:SceneTheme;exitProgress?:number;exitSnapshot?:ExitSceneSnapshot|null}>()
const emit=defineEmits<{wheel:[delta:number,mode:number,height:number];dragStart:[y:number];drag:[y:number];dragEnd:[cancelled:boolean];select:[logical:number];open:[];asset:[state:'loading'|'ready'|'failed',message:string]}>()
const host=ref<HTMLDivElement|null>(null),hover=ref(false)
let renderer:THREE.WebGLRenderer|null=null,scene:THREE.Scene|null=null,camera:THREE.OrthographicCamera|null=null,template:THREE.Object3D|null=null,observer:ResizeObserver|null=null
let entryRoot:THREE.Group|null=null
let hemisphere:THREE.HemisphereLight|null=null,keyLight:THREE.DirectionalLight|null=null,rimLight:THREE.DirectionalLight|null=null
let viewport=sceneViewport(1,1),dprQuery:MediaQueryList|null=null
let motionRaf=0,lastMotionTime:number|null=null
let alive=true,contextReady=true,visible=true,aspect=1,timer:ReturnType<typeof setTimeout>|null=null
const events=new AbortController(),loading=new AbortController(),ray=new THREE.Raycaster(),pointer=new THREE.Vector2()
const pool:Array<{root:THREE.Object3D;nodes:Map<string,THREE.Object3D>;reading:ReadingMotion;activity:OpticalActivity}>=[],ownedMaterials=new Set<THREE.Material>(),labelVariants:THREE.MeshStandardMaterial[]=[],ownedTextures=new Set<THREE.Texture>()
let liveHits:THREE.Object3D[]=[],down:{id:number;x:number;y:number;logical:number|null;moved:boolean}|null=null
function pick(e:PointerEvent){if(props.disabled||!camera||!host.value)return null;const box=host.value.getBoundingClientRect();const ndc=pointerNdc(e.clientX,e.clientY,box);if(!ndc)return null;pointer.set(ndc.x,ndc.y);ray.setFromCamera(pointer,camera);return ray.intersectObjects(liveHits,false)[0]?.object.userData.logical as number|undefined??null}
function pointerDown(e:PointerEvent){if(props.disabled||e.button!==0||down)return;down={id:e.pointerId,x:e.clientX,y:e.clientY,logical:pick(e),moved:false};host.value?.setPointerCapture(e.pointerId)}
function pointerMove(e:PointerEvent){if(props.disabled){stopPointer();hover.value=false;return}if(down&&down.id===e.pointerId){if(!down.moved&&Math.hypot(e.clientX-down.x,e.clientY-down.y)>6){down.moved=true;emit('dragStart',down.y)}if(down.moved)emit('drag',e.clientY)}else hover.value=pick(e)!==null}
function pointerUp(e:PointerEvent){if(props.disabled){stopPointer();return}if(!down||down.id!==e.pointerId)return;const start=down;down=null;if(host.value?.hasPointerCapture(e.pointerId))host.value.releasePointerCapture(e.pointerId);if(start.moved)emit('dragEnd',false);if(!start.moved&&start.logical!==null&&start.logical===pick(e))emit('select',start.logical)}
function stopPointer(){if(!down)return;const start=down;down=null;if(host.value?.hasPointerCapture(start.id))host.value.releasePointerCapture(start.id);if(start.moved)emit('dragEnd',true)}
function cancel(e:PointerEvent){if(down?.id===e.pointerId)stopPointer()}
function wheel(e:WheelEvent){if(props.disabled||props.frame.mode==='opening'||props.frame.mode==='detail'||props.frame.count<2||e.ctrlKey||e.metaKey||Math.abs(e.deltaY)<.05)return;e.preventDefault();emit('wheel',e.deltaY,e.deltaMode,host.value?.clientHeight??700)}
function render(){if(!renderer||!scene||!camera||!contextReady||!visible)return;const pose=entryScenePose(props.entryProgress??1),exit=exitScenePose(props.exitProgress??0),exitSample=props.exitSnapshot?sampleExitScene(props.exitSnapshot,props.exitProgress??0):null,sceneFrame=exitSample?.frame??props.frame,slots=exitSample?.slots??visibleSlots(props.frame.position,props.frame.count)
 if(entryRoot){entryRoot.matrixAutoUpdate=false;entryRoot.matrix.copy(sceneRootMatrix(props.entryProgress??1,props.exitProgress??0,aspect,viewport.rootY,props.exitSnapshot?.frame??props.frame));entryRoot.matrixWorldNeedsUpdate=true}
 camera.position.set(pose.cameraX,pose.cameraY,pose.cameraZ);camera.lookAt(pose.targetX,pose.targetY,pose.targetZ);camera.zoom=pose.cameraZoom;camera.updateProjectionMatrix();camera.updateMatrixWorld();liveHits=[];pool.forEach(p=>p.root.visible=false)
 for(const slot of slots){const item=pool[slot.slot];if(!item)continue;bindReadingIdentity(item.reading,slot.logical);bindOpticalActivity(item.activity,slot.logical);const t=slotTransform(slot,sceneFrame,aspect);item.root.visible=slot.visible;item.root.position.set(t.x,t.y,t.z);item.root.rotation.set(t.rotationX,t.rotationY,t.rotationZ,t.rotationOrder);item.root.scale.setScalar(t.scale);const label=item.nodes.get('ARCHIVE_label') as THREE.Mesh;const labelMaterial=label.material as THREE.MeshStandardMaterial;labelMaterial.map=labelVariants[slot.index]!.map;themeSceneMaterial(labelMaterial,'ARCHIVE_label',props.theme??'light');labelMaterial.opacity=slot.opacity*exit.opacity;const transparent=labelMaterial.opacity<1;if(labelMaterial.transparent!==transparent){labelMaterial.transparent=transparent;labelMaterial.needsUpdate=true}labelMaterial.depthWrite=!transparent;item.nodes.get('LID_panel')!.rotation.y=props.reduced?0:t.lidRotationY;item.nodes.get('OPTIC_main')!.rotation.z=item.reading.angle;const hit=item.nodes.get('HIT_archive')!;hit.userData.logical=slot.logical;if(!props.disabled&&exit.opacity>.8&&slot.visible&&slot.opacity>.2)liveHits.push(hit)
  item.root.traverse(n=>{if(!(n instanceof THREE.Mesh)||n.name==='HIT_archive'||n.name==='ARCHIVE_label')return;for(const m of Array.isArray(n.material)?n.material:[n.material]){readingMaterial(m,n.name,slot.opacity*exit.opacity,item.reading.glow,props.entries[slot.index]?.availability??'unknown',props.reduced||props.disabled||!isReadingSelected(slot.logical,props.frame)?0:item.activity.level);themeSceneMaterial(m,n.name,props.theme??'light',item.reading.glow)}})
 }scene.updateMatrixWorld(true);renderer.render(scene,camera)
}
function tickReading(now:number){motionRaf=0;if(!alive||!visible||!contextReady)return;const dt=lastMotionTime===null?1/60:Math.min(.05,Math.max(0,(now-lastMotionTime)/1000));lastMotionTime=now;for(const slot of props.exitSnapshot?.slots??visibleSlots(props.frame.position,props.frame.count)){const item=pool[slot.slot];if(item){updateReadingMotion(item.reading,slot.logical,isReadingSelected(slot.logical,props.frame)&&!(props.exitProgress??0),dt,props.reduced,readingFocusWeight(slot.logical,props.frame.position)*exitScenePose(props.exitProgress??0).opacity);updateOpticalActivity(item.activity,slot.logical,isReadingSelected(slot.logical,props.frame),props.disabled||(props.exitProgress??0)>0?'idle':props.activity??'idle',dt,props.reduced)}}render();if(!props.reduced||pool.some(p=>p.reading.glow>0&&p.reading.glow<.9995))motionRaf=requestAnimationFrame(tickReading)}
function startReading(){if(!motionRaf&&alive&&visible&&contextReady&&pool.length)motionRaf=requestAnimationFrame(tickReading)}
function updateTheme(){const light=sceneLighting(props.theme??'light');if(renderer)renderer.toneMappingExposure=light.exposure;if(hemisphere){hemisphere.color.set(light.sky);hemisphere.groundColor.set(light.ground);hemisphere.intensity=light.hemisphere}if(keyLight){keyLight.color.set(light.key);keyLight.intensity=light.keyIntensity}if(rimLight){rimLight.color.set(light.rim);rimLight.intensity=light.rimIntensity}}
function resize(){if(!host.value||!renderer||!camera)return;viewport=sceneViewport(host.value.clientWidth,host.value.clientHeight,window.devicePixelRatio);aspect=viewport.layoutAspect;renderer.setPixelRatio(viewport.dpr);renderer.setSize(viewport.width,viewport.height,false);camera.left=-viewport.halfWidth;camera.right=viewport.halfWidth;camera.top=viewport.halfHeight;camera.bottom=-viewport.halfHeight;camera.updateProjectionMatrix();render()}
function watchDpr(){dprQuery?.removeEventListener('change',onDprChange);dprQuery=window.matchMedia(`(resolution: ${window.devicePixelRatio||1}dppx)`);dprQuery.addEventListener('change',onDprChange,{once:true})}
function onDprChange(){resize();watchDpr()}

function dispose(){const geometries=new Set<THREE.BufferGeometry>();for(const root of [template,...pool.map(p=>p.root)])root?.traverse(n=>{if(n instanceof THREE.Mesh){geometries.add(n.geometry);for(const m of Array.isArray(n.material)?n.material:[n.material])ownedMaterials.add(m)}});geometries.forEach(g=>g.dispose());ownedMaterials.forEach(m=>m.dispose());const bitmaps=new Set<{close:()=>void}>();ownedTextures.forEach(t=>{const bitmap=t.source.data;if(bitmap&&typeof bitmap==='object'&&'close' in bitmap&&typeof bitmap.close==='function')bitmaps.add(bitmap as {close:()=>void});t.dispose()});bitmaps.forEach(bitmap=>bitmap.close());ownedTextures.clear();renderer?.dispose();renderer?.forceContextLoss();renderer?.domElement.remove()}
async function init(){emit('asset','loading','正在载入档案软盘');try{renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.06;renderer.domElement.setAttribute('aria-hidden','true');host.value!.prepend(renderer.domElement);scene=new THREE.Scene();entryRoot=new THREE.Group();scene.add(entryRoot);camera=new THREE.OrthographicCamera(-5,5,5,-5,.1,80);camera.position.set(0,0,20);camera.lookAt(0,0,0);camera.updateMatrixWorld();hemisphere=new THREE.HemisphereLight();scene.add(hemisphere);keyLight=new THREE.DirectionalLight();keyLight.position.set(-6,8,7);scene.add(keyLight);rimLight=new THREE.DirectionalLight();rimLight.position.set(8,-2,4);scene.add(rimLight);updateTheme();observer=new ResizeObserver(resize);observer.observe(host.value!);resize();timer=setTimeout(()=>loading.abort(),15000);const response=await fetch(`${import.meta.env.BASE_URL}models/sylanne-archive-v18.glb`,{signal:loading.signal});if(!response.ok)throw new Error(`模型载入失败 (${response.status})`);const bytes=await response.arrayBuffer();const gltf=await new GLTFLoader().parseAsync(bytes,'');for(const variant of gltf.scenes)variant.traverse(n=>{if(n instanceof THREE.Mesh)for(const m of Array.isArray(n.material)?n.material:[n.material]){ownedMaterials.add(m);if(m instanceof THREE.MeshStandardMaterial&&m.map)ownedTextures.add(m.map)}});if(timer)clearTimeout(timer);if(!alive){template=gltf.scene;dispose();return}template=gltf.scene;inspectModel(template);for(const entry of props.entries){const variant=gltf.scenes.find(s=>s.userData.entryId===entry.id);let label:THREE.Mesh|undefined;variant?.traverse(n=>{if(n instanceof THREE.Mesh&&n.userData.entryId===entry.id)label=n});if(!label)throw new Error('档案铭牌缺失：'+entry.title);const material=label.material as THREE.MeshStandardMaterial;labelVariants.push(material);ownedMaterials.add(material);if(material.map)ownedTextures.add(material.map)}
 for(let i=0;i<ARC_POOL_SIZE;i++){const root=template.clone(true),nodes=inspectModel(root);root.traverse(n=>{if(!(n instanceof THREE.Mesh))return;if(n.name==='HIT_archive'){n.material=new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false,colorWrite:false});ownedMaterials.add(n.material)}else{const clone=(m:THREE.Material)=>{const next=m.clone();next.userData.originalOpacity=m.opacity;ownedMaterials.add(next);return next};n.material=Array.isArray(n.material)?n.material.map(clone):clone(n.material)}});pool.push({root,nodes,reading:makeReadingMotion(),activity:makeOpticalActivity()});entryRoot!.add(root)}
 startReading();render();emit('asset','ready','真实档案模型已载入');renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();contextReady=false;cancelAnimationFrame(motionRaf);motionRaf=0;lastMotionTime=null;emit('asset','failed','三维上下文中断，文字控制仍可使用')},{signal:events.signal});renderer.domElement.addEventListener('webglcontextrestored',()=>{contextReady=true;lastMotionTime=null;emit('asset','ready','三维视图已恢复');startReading();render()},{signal:events.signal})
 }catch(error){if(timer)clearTimeout(timer);if(alive){dispose();renderer=null;emit('asset','failed',loading.signal.aborted?'模型载入超时':error instanceof Error?error.message:'三维视图暂不可用')}}}
onMounted(()=>{watchDpr();window.addEventListener('resize',resize,{signal:events.signal});window.visualViewport?.addEventListener('resize',resize,{signal:events.signal});host.value!.addEventListener('wheel',wheel,{passive:false,signal:events.signal});document.addEventListener('visibilitychange',()=>{visible=!document.hidden;if(visible){lastMotionTime=null;startReading();render()}else{cancelAnimationFrame(motionRaf);motionRaf=0;lastMotionTime=null}},{signal:events.signal});void init()})
watch(()=>[props.frame,props.reduced,props.entryProgress,props.activity,props.disabled,props.exitProgress,props.exitSnapshot],()=>{render();startReading()},{deep:true,flush:'post'})
watch(()=>props.theme,()=>{updateTheme();render()},{flush:'post'})
watch(()=>props.disabled,disabled=>{if(disabled){hover.value=false;stopPointer()}})
onBeforeUnmount(()=>{alive=false;dprQuery?.removeEventListener('change',onDprChange);cancelAnimationFrame(motionRaf);events.abort();loading.abort();if(timer)clearTimeout(timer);observer?.disconnect();dispose()})
</script>
<template><div ref="host" class="arc-viewport" :class="{'can-drag':!disabled&&frame.count>1&&frame.mode==='browse','has-card':!disabled&&hover}" :aria-disabled="disabled||undefined" @pointerdown="pointerDown" @pointermove="pointerMove" @pointerup="pointerUp" @pointercancel="cancel" @lostpointercapture="cancel" @pointerleave="hover=false"></div></template>
